package com.chatsystem.user.controller.group;
import com.chatsystem.shared.model.*;import com.chatsystem.shared.model.status.GroupRole;import com.chatsystem.shared.service.GroupService;import com.chatsystem.shared.session.UserSession;import com.chatsystem.user.navigation.*;import com.chatsystem.user.ui.cell.GroupMemberCell;import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.scene.layout.HBox;
public final class GroupDetailsController{private final GroupService groups;private final UserSession session;private final UserNavigator nav;private long id;private Runnable pending;@FXML private TextField nameField;@FXML private TextArea descriptionField;@FXML private ListView<ConversationMember> memberList;@FXML private Label groupFeedbackLabel,groupConfirmationLabel;@FXML private HBox groupConfirmationBar;public GroupDetailsController(GroupService g,UserSession s,UserNavigator n){groups=g;session=s;nav=n;}@FXML private void initialize(){}@FXML private void edit(){descriptionField.requestFocus();}@FXML private void save(){var r=groups.updateGroup(id,nameField.getText(),descriptionField.getText());feedback(r.isSuccess()?"Group updated":r.errors().get(0).message());}@FXML private void leave(){confirm("Leave this group?",()->{var r=groups.leaveGroup(id);if(r.isSuccess())nav.navigate(ViewRequest.of(UserRoute.GROUP_MANAGEMENT));else feedback(r.errors().get(0).message());});}@FXML private void confirmAction(){if(pending!=null)pending.run();cancelAction();}@FXML private void cancelAction(){pending=null;groupConfirmationBar.setManaged(false);groupConfirmationBar.setVisible(false);}@FXML private void invite(){nav.showDialog("/fxml/dialogs/invite-members.fxml","Invite member",c->((InviteMembersDialogController)c).present(id));}@FXML private void back(){nav.navigate(ViewRequest.of(UserRoute.GROUP_MANAGEMENT));}public void present(long groupId){id=groupId;Conversation g=groups.getGroups().stream().filter(x->x.getId()==id).findFirst().orElse(null);if(g==null){feedback("Group is unavailable");return;}nameField.setText(g.getName());descriptionField.setText(g.getDescription());memberList.setItems(groups.getMembers(id));memberList.setCellFactory(x->new GroupMemberCell(this::canManage,this::changeRole,this::requestRemove,this::isProtected));}private boolean canManage(){return groups.getMembers(id).stream().anyMatch(m->m.getUserId()==session.getCurrentUser().getId()&&m.getRole()==GroupRole.ADMIN);}private boolean isProtected(ConversationMember member){return member.getRole()==GroupRole.ADMIN&&groups.getMembers(id).stream().filter(m->m.getRole()==GroupRole.ADMIN).count()<=1;}private void changeRole(ConversationMember member,GroupRole role){var r=groups.changeRole(id,member.getUserId(),role);feedback(r.isSuccess()?"Role updated":r.errors().get(0).message());memberList.refresh();}private void requestRemove(ConversationMember member){confirm("Remove member #"+member.getUserId()+"?",()->{var r=groups.removeMember(id,member.getUserId());feedback(r.isSuccess()?"Member removed":r.errors().get(0).message());});}private void confirm(String text,Runnable r){pending=r;groupConfirmationLabel.setText(text);groupConfirmationBar.setManaged(true);groupConfirmationBar.setVisible(true);}private void feedback(String t){groupFeedbackLabel.setText(t);}}
